def count_good(records, threshold):
    count = 0
    for record in records:
        if record['loss'] < threshold:
            count += 1
    return count

def accuracy(preds, labels):
    if len(labels) == 0:
        return 0.0
    correct = 0
    for pred, label in zip(preds, labels):
        if pred == label:
            correct += 1
    return correct / len(labels)

